/* Flash cards USMLE: Embryology (505 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["embryology"] = [{"name":"01 - Embryology (Part 1).csv","cards":[["1e6q7ab1v","What does the sonic hedgehog (SHH) gene do in development?","Produced at the base of limbs in the zone of polarizing activity; patterns anterior-posterior axis and CNS development.","Eixo anteroposterior e SNC."],["14315cclg","What do mutations in sonic hedgehog cause?","Holoprosencephaly.","Holoprosencefalia."],["mds90h1rb","What does the Wnt-7 gene do?","Produced at the apical ectodermal ridge; organizes dorsal-ventral axis of limbs.","Eixo dorsoventral dos membros."],["4y5hnjo99","What does FGF do in limb development?","Produced at the apical ectodermal ridge; stimulates mitosis of underlying mesoderm, providing lengthening of limbs (proximal-distal axis).","Alongamento dos membros."],["1b4dogxsg","What do homeobox (HOX) genes do?","Code for transcription regulators that determine segmental organization of embryo in craniocaudal direction.","Organização craniocaudal."],["7nhb3i11s","What do HOX gene mutations cause?","Appendages in the wrong locations (e.g., synpolydactyly).","Membros no lugar errado."],["1vnf9wlnt","Which drug can alter HOX gene expression?","Isotretinoin (retinoic acid), causing teratogenic effects.","Isotretinoína."],["f8q9laufq","What happens in week 1 of human development?","Fertilization, cleavage, blastocyst formation; hCG secretion begins after implantation of the blastocyst (around day 6).","Fecundação e blastocisto."],["dxjh5xoba","When does implantation occur?","About 6 days after fertilization (within a week).","Cerca de 6 dias."],["1v9kasyc8","What happens in week 2 of development?","Bilaminar disc forms (epiblast and hypoblast). Rule of 2s: 2 germ layers, 2 cavities (amniotic cavity, yolk sac), 2 components of placenta (cytotrophoblast, syncytiotrophoblast).","Disco bilaminar."],["vpjxwz1g6","What happens in week 3 of development?","Trilaminar disc via gastrulation (3 germ layers); primitive streak, notochord, neural plate begin to form.","Disco trilaminar; gastrulação."],["1ggoqm9f7","What happens in weeks 3-8 (embryonic period)?","Organogenesis: neural tube forms (closes by week 4), extremely susceptible to teratogens.","Organogênese; fase sensível."],["gwo9bo1gn","What happens in week 4 of development?","Heart begins to beat; upper and lower limb buds begin to form. Rule of 4s: 4 limbs, 4 heart chambers.","Coração bate; brotos dos membros."],["xvtyj0558","When can fetal cardiac activity be seen on transvaginal ultrasound?","About week 6.","Semana 6."],["1kmzj20lc","What happens in week 8 of development?","Fetal movements begin; organogenesis nearly complete.","Movimentos fetais."],["pgqhazqp1","When do genitalia have male or female characteristics?","About week 10.","Semana 10."],["1pfxqpoyz","What does the ectoderm give rise to?","Surface ectoderm, neural tube, neural crest.","Ectoderma superficial, tubo neural, crista."],["1k7d0mla1","What does surface ectoderm form?","Epidermis, adenohypophysis (Rathke pouch), lens, epithelial linings of oral cavity and sensory organs of ear, olfactory epithelium, anal canal below pectinate line, parotid, sweat, and mammary glands.","Epiderme, cristalino, adeno-hipófise."],["16lz9xm1d","Which tumor arises from remnants of Rathke pouch?","Craniopharyngioma (benign, often calcified).","Craniofaringioma."],["wezkhp12c","What does neural tube (neuroectoderm) form?","Brain, retina, spinal cord, neurohypophysis, pineal gland, oligodendrocytes, astrocytes, ependymal cells.","Cérebro, retina, medula."],["1lm098pm5","What does neural crest form?","PNS (dorsal root ganglia, cranial nerves, autonomic ganglia), Schwann cells, melanocytes, adrenal medulla, enterochromaffin cells, pia/arachnoid, odontoblasts, parafollicular C cells, laryngeal cartilage, aorticopulmonary septum, skull bones.","Nervos periféricos, melanócitos, medula adrenal."],["1hon5v1wx","Mnemonic for neural crest derivatives?","MOTEL PASS: Melanocytes, Odontoblasts, Tracheal cartilage, Enterochromaffin cells, Laryngeal cartilage, Parafollicular cells, Adrenal medulla and all ganglia, Schwann cells, Spiral membrane (aorticopulmonary septum).","Mnemônico da crista neural."],["185gj1t1h","What does mesoderm form?","Muscle, bone, connective tissue, serous linings, spleen, cardiovascular structures, lymphatics, blood, wall of gut tube, upper vagina, kidneys, adrenal cortex, dermis, testes, ovaries, microglia, tracheal cartilage.","Músculo, osso, vasos, rins."],["1wriprxy8","What does the notochord become?","Induces neural plate formation; postnatal derivative is the nucleus pulposus of the intervertebral disc.","Núcleo pulposo."],["f62qpd11x","What is the VACTERL association?","Mesodermal defects: Vertebral defects, Anal atresia, Cardiac defects, Tracheo-Esophageal fistula, Renal defects, Limb defects (bone and muscle).","Defeitos mesodérmicos múltiplos."],["q230ed18p","What does endoderm form?","Gut tube epithelium (including anal canal above pectinate line), most of urethra and lower vagina, luminal epithelial derivatives (lungs, liver, gallbladder, pancreas, eustachian tube, thymus, parathyroid, thyroid follicular cells).","Epitélio do intestino e glândulas."],["19io9xgi8","What is an agenesis?","Absent organ due to absent primordial tissue.","Órgão ausente sem tecido primordial."],["5tthkd3qi","What is aplasia?","Absent organ despite presence of primordial tissue.","Órgão ausente com tecido primordial."],["dvae0y15d","What is hypoplasia?","Incomplete organ development; primordial tissue present.","Desenvolvimento incompleto."],["188ag4e17","What is a disruption?","Secondary breakdown of tissue that was previously normal (e.g., amniotic band syndrome).","Lesão de tecido normal."],["p9p3q97zq","What is a deformation?","Extrinsic mechanical distortion (e.g., congenital torticollis); occurs after the embryonic period.","Distorção mecânica externa."],["10fpja8a3","What is a malformation?","Intrinsic developmental defect, usually during the embryonic period (weeks 3-8).","Defeito intrínseco precoce."],["ffej90y2v","What is a sequence?","A single primary defect leading to a cascade of secondary anomalies (e.g., Potter sequence).","Cascata a partir de um defeito."],["dfb8k11cf","When is the fetus most susceptible to teratogens?","Weeks 3-8 (embryonic period, organogenesis).","Semanas 3 a 8."],["ffjdr112k","What is the effect of teratogens before week 3?","All-or-none effect: either the embryo dies or develops normally.","Tudo ou nada."],["1cr22srsg","What is the effect of teratogens after week 8?","Growth and function are affected rather than major structural malformation.","Afeta crescimento e função."],["rmd6vfljs","Teratogenic effect of ACE inhibitors?","Renal failure, oligohydramnios, hypocalvaria.","Insuficiência renal fetal."],["104hvzr15","Teratogenic effect of alkylating agents?","Absence of digits, multiple anomalies.","Ausência de dedos."],["witctlzmt","Teratogenic effect of aminoglycosides?","Ototoxicity (CN VIII damage).","Ototoxicidade."],["w5kdqdptb","Teratogenic effect of antiepileptic drugs?","Neural tube defects, cardiac defects, cleft palate, skeletal abnormalities (e.g., phalanx/nail hypoplasia, facial dysmorphism).","Defeitos do tubo neural e cardíacos."],["u216dz164","Which antiepileptic is the most teratogenic?","Valproate (neural tube defects, especially spina bifida).","Valproato."],["1oyhwbefe","Teratogenic effect of diethylstilbestrol (DES)?","Vaginal clear cell adenocarcinoma, congenital Müllerian anomalies.","Adenocarcinoma vaginal."],["lu85kw15o","Teratogenic effect of folate antagonists (methotrexate, trimethoprim)?","Neural tube defects.","Defeitos do tubo neural."],["gjbl06dkt","Teratogenic effect of isotretinoin?","Craniofacial, CNS, cardiac, thymic defects; contraception mandatory.","Defeitos craniofaciais e cardíacos."],["187n7sj16","Teratogenic effect of lithium?","Ebstein anomaly.","Anomalia de Ebstein."],["njmtw61hh","Teratogenic effect of methimazole?","Aplasia cutis congenita.","Aplasia cutis."],["c3crwpeoa","Teratogenic effect of tetracyclines?","Discolored teeth, inhibited bone growth.","Dentes manchados."],["lmizkd1wh","Teratogenic effect of thalidomide?","Limb defects (phocomelia, micromelia: flipper limbs).","Membros em nadadeira."],["17gralp58","Teratogenic effect of warfarin?","Bone deformities, fetal hemorrhage, abortion, ophthalmologic abnormalities, chondrodysplasia punctata.","Deformidades ósseas e hemorragia."],["pkr7oxfxv","Teratogenic effect of alcohol?","Fetal alcohol syndrome: most common cause of birth defects and intellectual disability.","Síndrome alcoólica fetal."],["g703zr16y","Teratogenic effect of cocaine?","Low birth weight, preterm birth, IUGR, placental abruption (vasoconstriction).","Baixo peso e descolamento."],["77eqh9158","Teratogenic effect of maternal smoking?","Low birth weight (leading cause in developed countries), preterm labor, placental problems, IUGR, SIDS, ADHD.","Baixo peso e parto prematuro."],["1gb3t891m","Teratogenic effect of iodine (lack or excess)?","Congenital goiter or hypothyroidism (cretinism).","Bócio e cretinismo."],["1ifkhtq8n","Teratogenic effect of maternal diabetes?","Caudal regression syndrome (anal atresia to sirenomelia), congenital heart defects (transposition, VSD), neural tube defects, macrosomia, neonatal hypoglycemia, polycythemia.","Regressão caudal e cardiopatias."],["if8jup145","Teratogenic effect of vitamin A excess?","Extremely high risk of spontaneous abortions and birth defects (cleft palate, cardiac abnormalities).","Abortos e malformações."],["qwc5zr189","Teratogenic effect of X-rays?","Microcephaly, intellectual disability; minimized with lead shielding.","Microcefalia."],["1sb8wpl9a","Teratogenic effect of maternal PKU?","Microcephaly, intellectual disability, growth retardation, congenital heart defects.","Microcefalia e cardiopatia."],["op0ru9mdl","Features of fetal alcohol syndrome?","Developmental delay, microcephaly, smooth philtrum, thin vermilion border (upper lip), small palpebral fissures, limb dislocation, heart defects; holoprosencephaly in severe cases.","Filtro liso e lábio fino."],["10zi51g1x","Mechanism of fetal alcohol syndrome brain anomalies?","Inhibition of cell migration.","Inibe migração celular."],["161e55v1m","What is neonatal abstinence syndrome?","Withdrawal in a neonate after in utero opioid exposure: irritability, high-pitched cry, tremor, poor feeding, diarrhea, sweating, seizures.","Abstinência do recém-nascido."],["oae6v110t","What are dizygotic (fraternal) twins?","Arise from 2 eggs separately fertilized by 2 different sperm; always 2 zygotes, dichorionic and diamniotic.","Dois óvulos e dois espermatozoides."],["11o4jpy19","How do monozygotic twins form?","Arise from 1 fertilized egg that splits into 2; type of placentation depends on timing of cleavage.","Um óvulo que se divide."],["1rh13b9ox","Monozygotic twin cleavage at 0-4 days?","Dichorionic, diamniotic (separate chorion and amnion).","Dicoriônicos e diamnióticos."],["1atxa198a","Monozygotic twin cleavage at 4-8 days?","Monochorionic, diamniotic (most common for monozygotic twins).","Monocoriônicos e diamnióticos."],["14i9y9m1s","Monozygotic twin cleavage at 8-12 days?","Monochorionic, monoamniotic.","Monocoriônicos e monoamnióticos."],["1pstwf31o","Monozygotic twin cleavage after 13 days?","Monochorionic, monoamniotic, conjoined twins.","Gêmeos siameses."],["1yczh0g16","What is twin-twin transfusion syndrome?","Occurs in monochorionic twins with vascular anastomoses: donor twin becomes anemic with oligohydramnios; recipient becomes polycythemic with polyhydramnios.","Um gêmeo doa sangue ao outro."],["1d239ue17","What is the fetal component of the placenta?","Cytotrophoblast (inner layer of chorionic villi) and syncytiotrophoblast (outer layer).","Cito e sinciciotrofoblasto."],["mgywt8omi","What does the syncytiotrophoblast secrete?","hCG (structurally similar to LH; stimulates corpus luteum to secrete progesterone during the first trimester).","hCG."],["1vguqgvec","Why does syncytiotrophoblast lack MHC class I?","Decreases chance of maternal immune attack on the fetus.","Evita ataque imune."],["dgpxnk1pa","What is the maternal component of the placenta?","Decidua basalis (derived from endometrium); maternal blood in lacunae.","Decídua basal."],["1klg6a113","What is placenta accreta?","Abnormal attachment of the placenta to the myometrium without invading it (defective decidua basalis).","Placenta presa ao miométrio."],["19qjk3z36","What is placenta increta vs percreta?","Increta: invades into myometrium. Percreta: penetrates through the myometrium into the uterine serosa or adjacent organs.","Invade ou atravessa o miométrio."],["ljai1wria","Risk factors for placenta accreta spectrum?","Prior cesarean section, prior uterine surgery, placenta previa.","Cesárea prévia e placenta prévia."],["11lqchfqy","What is placenta previa?","Attachment of the placenta to the lower uterine segment covering the internal cervical os; painless third-trimester bleeding.","Placenta sobre o colo."],["no2lhq18d","What is placental abruption?","Premature separation of placenta from the uterine wall before delivery; painful bleeding; risk factors: hypertension, trauma, cocaine, smoking.","Separação precoce da placenta."],["xnlkx2vzk","What does the umbilical cord contain?","Two umbilical arteries (deoxygenated blood from fetus) and one umbilical vein (oxygenated blood to fetus).","Duas artérias e uma veia."],["1o7k53715","What does a single umbilical artery suggest?","Possible congenital and chromosomal anomalies (renal, cardiac).","Anomalias associadas."],["1fttvw5u1","What do the umbilical arteries and vein derive from?","Allantois.","Alantoide."],["shymye1mr","What is the allantois and its remnant?","Extension of the yolk sac into the umbilical cord; becomes the urachus, then the median umbilical ligament.","Úraco vira ligamento umbilical mediano."],["1ezfrp6tk","What is a patent urachus?","Failure of the urachus to obliterate, causing urine discharge from the umbilicus.","Urina pelo umbigo."],["mgfugmowc","What is a urachal cyst?","Partial failure of urachal obliteration; fluid-filled cavity, risk of infection and adenocarcinoma.","Cisto do úraco."],["o16ayl9p5","What is a vesicourachal diverticulum?","Failure of the urachus to close near the bladder, causing an outpouching of the bladder.","Divertículo da bexiga."],["o9bomx1rz","What is the vitelline duct?","Connection between the yolk sac and midgut lumen; normally obliterates during week 7.","Liga saco vitelino ao intestino."],["chhp691mo","What is a Meckel diverticulum?","Partial closure of the vitelline duct with patent portion attached to the ileum (true diverticulum); may contain ectopic gastric or pancreatic tissue.","Ducto vitelino persistente."],["kraail1dt","Rule of 2s for Meckel diverticulum?","2 times as likely in males, 2 inches long, 2 feet from the ileocecal valve, 2% of population, presents in first 2 years of life, 2 types of epithelium.","Regra dos 2."],["1v7zzca5d","Diagnosis of Meckel diverticulum?","Technetium-99m pertechnetate scan detects ectopic gastric mucosa.","Cintilografia com tecnécio."],["1poytjrcs","What is a vitelline fistula?","Failure of vitelline duct to close, causing meconium discharge from the umbilicus.","Fezes pelo umbigo."],["1cpvcmg1c","Where does fetal erythropoiesis occur, in order?","Yolk sac (weeks 3-8), liver (weeks 6-30), spleen (weeks 10-28), bone marrow (week 18 to adult). Young Liver Synthesizes Blood.","Saco vitelino, fígado, baço, medula."],["1j3awdycu","What is the composition of fetal hemoglobin?","Alpha2 gamma2.","Duas alfa e duas gama."],["11di5i0j3","Why does fetal hemoglobin have higher O2 affinity than adult Hb?","HbF binds 2,3-BPG less avidly, allowing O2 transfer from maternal to fetal circulation.","Liga menos 2,3-BPG."],["th05851c0","What is the composition of embryonic hemoglobins?","Zeta2 epsilon2 and others (in yolk sac stage).","Zeta e épsilon."],["1rxuxel72","What is the role of hCG in early pregnancy?","Maintains the corpus luteum (progesterone) during the first trimester.","Mantém o corpo lúteo."],["1uh6ug71n","When does the placenta take over progesterone production?","By the second trimester (about weeks 8-10).","Semanas 8 a 10."],["9qfmwvdoh","What hormone tests are used to detect pregnancy?","hCG in urine or serum; detectable about 1 week after conception.","hCG."],["1gfm2gjc8","What conditions cause elevated hCG?","Multiple gestation, hydatidiform moles, choriocarcinoma, Down syndrome.","Gêmeos, mola, Down."],["15saeuhjh","What conditions cause low hCG?","Ectopic pregnancy, failing pregnancy, Edwards syndrome, Patau syndrome.","Ectópica e trissomias 13 e 18."],["25fyasyo6","What is the role of human placental lactogen?","Increases maternal insulin resistance to supply glucose to the fetus; stimulates mammary development.","Resistência à insulina materna."],["10bdckpuk","What is the role of progesterone in pregnancy?","Maintains the endometrium, decreases uterine contractility, increases body temperature.","Mantém o endométrio."],["m3nt9k1ax","What is the role of estriol in pregnancy?","Made by placenta from fetal adrenal DHEA-S; marker of fetal well-being.","Bem-estar fetal."],["1o2ydwo1d","What is the primitive streak?","Thickening in the epiblast at day 15 that initiates gastrulation.","Inicia a gastrulação."],["1owwe3t1n","What is sacrococcygeal teratoma?","Tumor from persistent primitive streak remnants; most common tumor in newborns.","Tumor neonatal mais comum."],["1jjsnxn6k","What does the epiblast give rise to?","All three germ layers (ectoderm, mesoderm, endoderm).","Três folhetos."],["h018551td","What does the hypoblast give rise to?","Extraembryonic endoderm (yolk sac).","Saco vitelino."],["qzr2n918m","What is the trophoblast?","Outer layer of the blastocyst that forms the fetal part of the placenta.","Parte fetal da placenta."],["7raqg716t","What is the inner cell mass?","Cells of the blastocyst that become the embryo.","Vira o embrião."],["h5t1lo16t","What hormone does the corpus luteum secrete in early pregnancy?","Progesterone (and estrogen), stimulated by hCG.","Progesterona."],["1tppgajnu","When does the neural tube close?","By the end of week 4 (anterior neuropore ~day 25, posterior ~day 28).","Fim da semana 4."],["r4xxhw1ti","What is the effect of maternal folate deficiency on neural tube development?","Increased risk of neural tube defects (failure of closure).","Defeitos do tubo neural."],["wsqaq1s9a","Which maternal infections are teratogenic (TORCH)?","Toxoplasma, Other (syphilis, VZV, parvovirus B19, HIV, Zika), Rubella, CMV, HSV.","Infecções congênitas."],["1qqkrfa1i","Classic findings of congenital toxoplasmosis?","Chorioretinitis, hydrocephalus, diffuse intracranial calcifications, ring-enhancing lesions.","Coriorretinite e calcificações difusas."],["15zotoe1e","Classic findings of congenital rubella?","PDA or pulmonary artery hypoplasia, cataracts, deafness, blueberry muffin rash.","PCA, catarata, surdez."],["16i5gw71b","Classic findings of congenital CMV?","Hearing loss, seizures, petechial rash, blueberry muffin rash, chorioretinitis, periventricular calcifications.","Surdez e calcificações periventriculares."],["c4wkmqze2","Classic findings of congenital syphilis?","Early: rhinorrhea (snuffles), maculopapular rash, hepatomegaly. Late: saddle nose, Hutchinson teeth, mulberry molars, saber shins, CN VIII deafness.","Nariz em sela e dentes de Hutchinson."],["1hicjt2k2","Classic findings of congenital Zika?","Microcephaly, ocular anomalies, intracranial calcifications.","Microcefalia."],["64mvv8g4o","Classic findings of congenital varicella?","Cutaneous scarring, limb hypoplasia, cataracts, microcephaly.","Cicatrizes e membros hipoplásicos."],["1seyxycls","Classic findings of congenital parvovirus B19?","Hydrops fetalis (fetal anemia, high-output heart failure).","Hidropisia fetal."],["w36a3017b","What is amniotic band syndrome?","Fibrous bands from amnion rupture entangle fetal parts, causing limb amputations, constrictions, and craniofacial defects.","Bandas amnióticas amputam."],["1vegqkvoz","What is oligohydramnios and its causes?","Too little amniotic fluid: placental insufficiency, bilateral renal agenesis, posterior urethral valves, ARPKD, ruptured membranes.","Pouco líquido amniótico."],["vsne0tpmg","What is Potter sequence?","Oligohydramnios causes compression of the fetus: limb deformities, flat face, low-set ears, pulmonary hypoplasia (cause of death).","Compressão fetal por oligoidrâmnio."],["1yxyc131j","What is polyhydramnios and its causes?","Too much amniotic fluid: maternal diabetes, fetal GI obstruction (duodenal/esophageal atresia), anencephaly (impaired swallowing), multiple gestation.","Excesso de líquido amniótico."],["928sugh97","What is the main source of amniotic fluid after 16 weeks?","Fetal urine.","Urina fetal."],["22blju124","How is amniotic fluid removed?","Fetal swallowing and absorption by the GI tract.","Deglutição fetal."],["1ymkk9a1p","What is caudal regression syndrome?","Agenesis or hypoplasia of the sacrum and lower spine; associated with maternal diabetes.","Agenesia sacral."],["1md5vew12","When does the fetal heart start beating?","About day 22 (week 4).","Dia 22."],["x6spt01e4","When does the fetus produce urine?","Starts around week 10, important after week 16 for amniotic fluid.","Semana 10."],["g23eak1yj","What is the lecithin/sphingomyelin ratio threshold for lung maturity?","Greater than 2.0.","Maior que 2."],["1jbacrl1w","When does surfactant production begin and reach adequacy?","Begins around 20-26 weeks; adequate by about 35 weeks.","Começa às 20 semanas."],["q5p36e18f","Which hormone accelerates fetal lung maturity?","Glucocorticoids (given to mothers in preterm labor between 24-34 weeks).","Corticoides."],["10bdozaic","What is the effect of maternal hyperglycemia on fetal lung maturity?","Fetal hyperinsulinemia inhibits surfactant production, delaying lung maturity.","Atrasa a maturidade pulmonar."],["9za92q1ew","What is a hydatidiform mole?","Cystic swelling of chorionic villi and trophoblast proliferation; complete or partial.","Proliferação trofoblástica."],["pg2cfo1tz","Karyotype of a complete hydatidiform mole?","46,XX (most common) or 46,XY; entirely paternal (empty egg fertilized by one sperm that duplicates, or by two sperm).","Totalmente paterna, 46,XX."],["19xvlgu1h","Karyotype of a partial hydatidiform mole?","69,XXX, 69,XXY, or 69,XYY: normal egg fertilized by two sperm; fetal parts present.","Triploide."],["1tysrkmlx","Features of complete mole?","Very high hCG, uterus larger than dates, snowstorm/cluster of grapes on ultrasound, no fetal parts, higher risk of choriocarcinoma.","hCG muito alto e útero grande."],["7vz5m5c0o","What should be done after evacuation of a molar pregnancy?","Serial hCG monitoring to detect persistent gestational trophoblastic disease or choriocarcinoma.","Acompanhar hCG."],["584w5e1fh","What is the role of the zona pellucida?","Glycoprotein layer around the oocyte preventing polyspermy (cortical reaction) and blastocyst adherence before implantation.","Bloqueia polispermia."],["1aphh3b1q","Where does fertilization usually occur?","Ampulla of the fallopian tube.","Ampola da trompa."],["drw2v91mq","What is the most common site of ectopic pregnancy?","Ampulla of the fallopian tube.","Ampola."],["1j9nslct1","Risk factors for ectopic pregnancy?","History of PID/salpingitis, prior ectopic, tubal surgery, IUD, IVF, smoking.","DIP, cirurgia tubária, DIU."],["7su0zbo7i","What is the cortical reaction?","Release of cortical granules after sperm penetration that alters the zona pellucida to block polyspermy.","Bloqueio da polispermia."],["jxsyk11sm","What is the acrosome reaction?","Release of enzymes from the sperm acrosome allowing penetration of the zona pellucida.","Enzimas para atravessar a zona."],["1xghyq3ho","Where does sperm capacitation occur?","In the female reproductive tract (removal of glycoproteins from the sperm head).","No trato feminino."],["q5g9k31rh","What is a morula?","Solid ball of about 16 cells formed by cleavage around day 3-4.","Bola de 16 células."],["1ixfe9d1l","What is a blastocyst?","Fluid-filled structure (day 5) with inner cell mass and trophoblast, ready for implantation.","Estrutura com cavidade."],["8qapvqh78","Which layer of the trophoblast invades the endometrium?","Syncytiotrophoblast.","Sinciciotrofoblasto."],["1k5r2ncck","What is the decidua?","Endometrium of pregnancy: decidua basalis (placental site), capsularis (covers embryo), parietalis (rest of uterus).","Endométrio da gravidez."],["drqgb11w8","What is the chorion?","Fetal membrane formed by trophoblast and extraembryonic mesoderm; chorion frondosum forms the fetal placenta.","Membrana fetal externa."],["10qoi1ls8","What is the amnion?","Innermost fetal membrane enclosing the amniotic cavity, derived from the epiblast.","Membrana interna."],["14l1l301u","What is the role of the yolk sac in humans?","Early blood cell formation, primordial germ cell origin, and part incorporated into the gut.","Células sanguíneas e germinativas."],["ya4i8t13z","What is gastrulation?","Formation of the trilaminar disc (ectoderm, mesoderm, endoderm) via the primitive streak in week 3.","Formação dos três folhetos."],["k6veel1j6","What is the oropharyngeal membrane?","Site at the cranial end where ectoderm and endoderm are in contact without mesoderm; ruptures to form the mouth opening.","Futura boca."],["xlk8wz1va","What is the cloacal membrane?","Site at the caudal end where ectoderm and endoderm meet; future anus and urogenital openings.","Futuros ânus e uretra."],["hh2hx5gwy","What are the three types of mesoderm?","Paraxial (somites), intermediate (urogenital), and lateral plate (somatic and splanchnic) mesoderm.","Paraxial, intermediário e lateral."],["tdw5xji28","What does somatic (parietal) lateral plate mesoderm form?","Body wall, limb connective tissue and bones, parietal serous membranes.","Parede corporal e membros."],["1dsa4111v","What does splanchnic (visceral) lateral plate mesoderm form?","Visceral serous membranes, gut wall smooth muscle and connective tissue, heart, blood vessels.","Vísceras, coração e vasos."],["16shaxagw","Teratogenic effect of fluconazole at high doses?","Craniofacial and skeletal abnormalities (high-dose, prolonged use).","Anomalias craniofaciais."],["e3827dh4s","Teratogenic effect of carbamazepine?","Neural tube defects, craniofacial defects, fingernail hypoplasia, developmental delay.","Defeitos do tubo neural."],["1nzer0t1k","Teratogenic effect of phenytoin?","Fetal hydantoin syndrome: microcephaly, dysmorphic craniofacial features, hypoplastic nails and distal phalanges, cardiac defects, cleft lip/palate.","Síndrome da hidantoína fetal."],["10mro6bgz","Teratogenic effect of mycophenolate?","Ear, face, and heart defects; first-trimester pregnancy loss.","Defeitos de orelha e face."],["16xwell15","Teratogenic effect of leflunomide?","Highly teratogenic; contraindicated in pregnancy (use cholestyramine washout).","Muito teratogênico."],["4h8dn91a2","Teratogenic effect of misoprostol in early pregnancy?","Möbius sequence and limb defects (and abortion).","Síndrome de Möbius."],["ghmhrxvfl","Teratogenic effect of statins?","Contraindicated in pregnancy due to theoretical risk to fetal development (cholesterol needed for development).","Contraindicadas na gestação."]]},{"name":"02 - Embryology (Part 2).csv","cards":[["1yyz4149f","When does the heart tube begin to beat?","Around week 4 (day 22).","Semana 4."],["ixirniudi","Which gene defect causes dextrocardia and situs inversus by affecting cardiac looping?","Defects in left-right dynein (as in primary ciliary dyskinesia/Kartagener syndrome).","Defeito da dineína."],["1xhzn515j","What does cardiac looping establish?","Left-right orientation of the heart; begins in week 4.","Orientação esquerda-direita."],["txi29w1ny","What does the truncus arteriosus give rise to?","Ascending aorta and pulmonary trunk.","Aorta ascendente e tronco pulmonar."],["6h38aosa4","What does the bulbus cordis give rise to?","Smooth parts (outflow tract) of the left and right ventricles.","Partes lisas dos ventrículos."],["19atui2r7","What does the endocardial cushion give rise to?","Atrial septum, membranous interventricular septum, AV and semilunar valves.","Septos e valvas."],["17ivh1kr0","What does the primitive atrium give rise to?","Trabeculated part of the left and right atria.","Átrios trabeculados."],["2uphye1jy","What does the primitive ventricle give rise to?","Trabeculated part of the left and right ventricles.","Ventrículos trabeculados."],["1vyrj45um","What does the primitive pulmonary vein give rise to?","Smooth part of the left atrium.","Parte lisa do átrio esquerdo."],["bbwgze1dg","What does the left horn of the sinus venosus give rise to?","Coronary sinus.","Seio coronário."],["7vr7r52im","What does the right horn of the sinus venosus give rise to?","Smooth part of the right atrium (sinus venarum).","Parte lisa do átrio direito."],["13wmiy6c3","What do the right common and anterior cardinal veins give rise to?","Superior vena cava.","Veia cava superior."],["ijop5rzdl","What does the posterior, subcardinal, and supracardinal vein system give rise to?","Inferior vena cava.","Veia cava inferior."],["169ag0nym","First step of atrial septation?","Septum primum grows toward the endocardial cushions, narrowing the ostium primum.","Septo primo cresce."],["r68zbx1mh","Second step of atrial septation?","Ostium secundum forms in septum primum as the ostium primum closes.","Surge o óstio secundo."],["q1qdzifnl","Third step of atrial septation?","Septum secundum develops as the ostium secundum maintains right-to-left shunt.","Septo secundo se forma."],["165l2ta1c","What is the foramen ovale?","Opening in the septum secundum; the remaining septum primum forms its valve.","Abertura com válvula do septo primo."],["177540b14","What causes the foramen ovale to close at birth?","Increased left atrial pressure and decreased right atrial pressure push the septum primum against the septum secundum.","Pressão esquerda maior que direita."],["k8zd4de5t","What remnant does the foramen ovale leave?","Fossa ovalis.","Fossa oval."],["10bbx3w1k","What is a patent foramen ovale?","Failure of septum primum and secundum to fuse after birth; present in about 1 in 4 adults; can allow paradoxical emboli.","Septos não fundidos."],["otwkj313f","How does the muscular interventricular septum form?","It grows upward from the floor of the ventricle, leaving an interventricular foramen.","Cresce do assoalho ventricular."],["p4kg8f1wb","What closes the interventricular foramen?","Aorticopulmonary septum rotates and fuses with the muscular septum and endocardial cushion tissue to form the membranous septum.","Septo membranoso."],["fx0gnie2i","What is the most common location of VSD?","Membranous septum.","Septo membranoso."],["1bxtxxswt","How does the aorticopulmonary septum form?","Truncal and bulbar ridges (from neural crest) spiral and fuse to form the aorticopulmonary septum dividing the aorta and pulmonary trunk.","Cristas espirais da crista neural."],["w8oo3r1dr","Which defect results from failure of neural crest migration to the outflow tract?","Conotruncal anomalies: tetralogy of Fallot, transposition, persistent truncus arteriosus.","Anomalias conotruncais."],["10clf4z4w","How do the semilunar valves form?","From endocardial cushions of the outflow tract.","Coxins do trato de saída."],["veujtu1ot","How do the AV valves form?","From fused endocardial cushions of the AV canal (valves, chordae, papillary muscles develop from ventricular myocardium remodeling).","Coxins atrioventriculares."],["19gqh9uzg","Which valvular abnormalities can result from endocardial cushion defects?","Stenosis, regurgitation, atresia (e.g., tricuspid atresia), or displacement (Ebstein anomaly).","Estenose, insuficiência, Ebstein."],["1iwarx318","What is the umbilical vein's oxygen saturation in fetal circulation?","About 80% saturated (PO2 ~30 mmHg).","Cerca de 80%."],["1ho93iwei","Where does most oxygenated blood from the umbilical vein go?","Through the ductus venosus into the IVC, bypassing the hepatic circulation.","Ducto venoso para a cava."],["1jjxo3n1o","How does oxygenated blood reach the fetal brain?","Through the foramen ovale from the right atrium to the left atrium, then left ventricle to the ascending aorta.","Pelo forame oval."],["18qjierhy","How does deoxygenated blood from the SVC bypass the lungs?","Enters the right ventricle, then the pulmonary artery, then the ductus arteriosus to the descending aorta.","Pelo canal arterial."],["rwancxk1x","Why does blood bypass the fetal lungs?","High pulmonary vascular resistance in fetal lungs (partly due to low O2 tension).","Resistência pulmonar alta."],["zxgdqnu3z","What happens to fetal circulation at birth?","Infant breathes, pulmonary vascular resistance falls, left atrial pressure rises above right atrial pressure, foramen ovale closes; increased O2 and decreased prostaglandins close the ductus arteriosus.","Pulmão abre e canais fecham."],["4bdx9a4y6","Which drug closes a patent ductus arteriosus?","Indomethacin (or ibuprofen, acetaminophen).","Indometacina."],["1cdkpmt1z","Which drug keeps the ductus arteriosus open?","Prostaglandins E1 and E2.","Prostaglandina E1."],["6vy13b1j1","What is the adult remnant of the ductus arteriosus?","Ligamentum arteriosum.","Ligamento arterioso."],["57rx371gb","What is the adult remnant of the ductus venosus?","Ligamentum venosum.","Ligamento venoso."],["ppqv0p1xh","What is the adult remnant of the foramen ovale?","Fossa ovalis.","Fossa oval."],["6m6ij31vb","What is the adult remnant of the allantois/urachus?","Median umbilical ligament.","Ligamento umbilical mediano."],["f5gr77g6i","What is the adult remnant of the umbilical arteries?","Medial umbilical ligaments (distal portions); proximal portions become superior vesical arteries.","Ligamentos umbilicais mediais."],["1czxhwo1e","What is the adult remnant of the umbilical vein?","Ligamentum teres hepatis (round ligament), in the falciform ligament.","Ligamento redondo."],["cqumz0p52","What is the adult remnant of the notochord?","Nucleus pulposus.","Núcleo pulposo."],["2p5t8615f","What forms the aortic arch?","4th aortic arch on the left.","Quarto arco esquerdo."],["6jutjviy1","What does the 1st aortic arch become?","Part of the maxillary artery (branch of external carotid). 1st arch is maximal.","Artéria maxilar."],["1s2il6djt","What does the 2nd aortic arch become?","Stapedial artery and hyoid artery. Second = stapedial.","Artéria estapédica."],["w66xyg1a9","What does the 3rd aortic arch become?","Common carotid artery and proximal internal carotid artery. C is the 3rd letter.","Carótida comum."],["1rnuh2dr1","What does the 4th aortic arch become?","On the left, aortic arch; on the right, proximal part of the right subclavian artery. 4th arch (4 limbs) = systemic.","Arco aórtico e subclávia direita."],["skhfjb1q7","What does the 6th aortic arch become?","Proximal pulmonary arteries and, on the left, the ductus arteriosus. 6th arch = pulmonary and the pulmonary-to-systemic shunt.","Artérias pulmonares e canal arterial."],["1nsm10913","Why does the left recurrent laryngeal nerve loop around the aortic arch but the right loops around the subclavian?","The nerves follow the 6th arch; the right 6th arch distal part regresses, so the right nerve rises to loop around the 4th arch (subclavian).","Segue o sexto arco."],["1ndnkpg1h","What is a vascular ring?","Abnormal aortic arch development encircling trachea and esophagus (e.g., double aortic arch), causing stridor and dysphagia.","Anel vascular comprime traqueia."],["k7bajl17v","What are the components of the pharyngeal apparatus?","Clefts (ectoderm), arches (mesoderm and neural crest), pouches (endoderm). CAP covers outside to inside.","Fendas, arcos e bolsas."],["d1q385xh4","What do pharyngeal clefts form?","1st cleft forms the external auditory meatus; 2nd-4th clefts form temporary cervical sinuses obliterated by proliferation of 2nd arch mesenchyme.","Meato acústico externo."],["1t61dzyxz","What is a branchial cleft cyst?","Persistent cervical sinus (usually 2nd cleft): painless lateral neck mass anterior to the sternocleidomastoid that does not move with swallowing.","Cisto cervical lateral."],["zb1pa4sd9","How is a branchial cleft cyst different from a thyroglossal duct cyst?","Branchial cleft cyst is lateral; thyroglossal duct cyst is midline and moves with swallowing.","Lateral versus linha média."],["1g1l5bigg","Which muscles derive from the 1st pharyngeal arch?","Muscles of mastication (temporalis, masseter, lateral and medial pterygoids), mylohyoid, anterior belly of digastric, tensor tympani, anterior two-thirds of tongue, tensor veli palatini.","Músculos da mastigação."],["6my46wqhj","Which cartilage structures derive from the 1st pharyngeal arch?","Meckel cartilage: mandible, malleus and incus, sphenomandibular ligament.","Mandíbula, martelo e bigorna."],["16z0n20eo","Which nerves innervate 1st arch derivatives?","CN V2 and V3 (chew).","Nervo trigêmeo."],["tpn7rrpl6","Which congenital malformations involve the 1st arch?","Pierre Robin sequence (micrognathia, glossoptosis, cleft palate, airway obstruction) and Treacher Collins syndrome (neural crest dysfunction: mandibular hypoplasia, facial abnormalities).","Pierre Robin e Treacher Collins."],["mvwrnk1b4","Which muscles derive from the 2nd pharyngeal arch?","Muscles of facial expression, stapedius, stylohyoid, platysma, posterior belly of digastric.","Músculos da mímica facial."],["1rrq8t2zn","Which cartilage structures derive from the 2nd pharyngeal arch?","Reichert cartilage: stapes, styloid process, lesser horn of hyoid, stylohyoid ligament.","Estribo e estiloide."],["gj8c7q1kh","Which nerve innervates 2nd arch derivatives?","CN VII (smile/facial expression).","Nervo facial."],["1ej5m4d15","Which muscle derives from the 3rd pharyngeal arch?","Stylopharyngeus.","Estilofaríngeo."],["1nyegvf15","Which cartilage structures derive from the 3rd pharyngeal arch?","Greater horn of hyoid.","Corno maior do hioide."],["fhe1e3g5t","Which nerve innervates 3rd arch derivatives?","CN IX (swallow, stylopharyngeus up).","Nervo glossofaríngeo."],["899o1zft3","Which muscles derive from the 4th and 6th pharyngeal arches?","4th: most pharyngeal constrictors, cricothyroid, levator veli palatini. 6th: all intrinsic muscles of larynx except cricothyroid.","Constritores e músculos da laringe."],["1lrwfo7mf","Which cartilages derive from the 4th and 6th arches?","Arytenoids, cricoid, corniculate, cuneiform, thyroid cartilages.","Cartilagens da laringe."],["rjzyo71cf","Which nerves innervate 4th and 6th arch derivatives?","4th: CN X superior laryngeal branch (simply swallow). 6th: CN X recurrent laryngeal branch (speak).","Nervo vago."],["zw3aea1mx","Which arches contribute to the tongue?","Arches 1 and 2 form the anterior two-thirds (sensation via CN V3, taste via CN VII); arches 3 and 4 form the posterior one-third (sensation and taste mainly CN IX, extreme posterior CN X).","Arcos 1 a 4."],["ieqqr710x","Which nerve provides motor innervation to the tongue?","CN XII (hypoglossal), except palatoglossus (CN X).","Hipoglosso."],["3ded039zo","What does the 1st pharyngeal pouch become?","Middle ear cavity, eustachian tube, mastoid air cells.","Ouvido médio e tuba."],["1cwxjel1r","What does the 2nd pharyngeal pouch become?","Epithelial lining of palatine tonsil.","Tonsila palatina."],["15onccg1d","What does the 3rd pharyngeal pouch become?","Dorsal wings: inferior parathyroids. Ventral wings: thymus.","Paratireoides inferiores e timo."],["r8qbe5p3e","What does the 4th pharyngeal pouch become?","Dorsal wings: superior parathyroids. Ventral wings: ultimopharyngeal body (parafollicular C cells of thyroid).","Paratireoides superiores e células C."],["cj6bwn9s5","Why are the inferior parathyroids from the 3rd pouch and superior from the 4th?","The 3rd pouch structures (thymus and parathyroids) migrate further caudally, ending below the 4th pouch parathyroids.","Migram mais para baixo."],["6enco44gw","Which pouch defects cause DiGeorge syndrome?","Aberrant development of 3rd and 4th pouches: T-cell deficiency (thymic aplasia) and hypocalcemia (parathyroid aplasia).","3ª e 4ª bolsas."],["nxl687nai","Where does the thyroid gland develop?","From an outpouching (thyroid diverticulum) of the floor of the primitive pharynx at the foramen cecum, descending into the neck.","Forame cego da língua."],["yu962a159","What is the foramen cecum?","Normal remnant of the thyroglossal duct at the base of the tongue.","Resto do ducto tireoglosso."],["unjv3j1ji","What is the most common ectopic thyroid tissue site?","Base of the tongue (lingual thyroid).","Base da língua."],["15mvrq91x","What is a thyroglossal duct cyst?","Persistent thyroglossal duct: anterior midline neck mass that moves with swallowing or protrusion of the tongue.","Massa na linha média que sobe."],["1h7e0kqz3","Where do the parafollicular C cells come from?","Neural crest cells via the 4th pharyngeal pouch (ultimopharyngeal body).","Quarta bolsa."],["1hsfxspag","How does the primary palate form?","Fusion of the medial nasal prominences (intermaxillary segment).","Proeminências nasais mediais."],["r5bokv21n","How does the secondary palate form?","Fusion of the two lateral palatine shelves (from maxillary prominences) with each other and with the nasal septum.","Placas palatinas laterais."],["1liq331u6","What causes cleft lip?","Failure of fusion of the maxillary and merged medial nasal processes (formation of the primary palate).","Falha da fusão do lábio."],["3niwl3rei","What causes cleft palate?","Failure of fusion of the two lateral palatine shelves or failure of fusion of lateral palatine shelves with the nasal septum and/or primary palate.","Falha da fusão do palato."],["48nl3cvdv","Are cleft lip and cleft palate related embryologically?","They have distinct mechanisms but often occur together; multifactorial inheritance.","Mecanismos diferentes."],["2w80rb95p","What does the frontonasal prominence form?","Forehead, bridge of nose, medial and lateral nasal prominences.","Testa e nariz."],["1d550xr15","What does the maxillary prominence form?","Cheeks, lateral upper lip, secondary palate.","Bochechas e palato."],["41zh2n1wy","What does the mandibular prominence form?","Lower lip, chin, lower jaw.","Mandíbula e lábio inferior."],["1dcte4mvn","Which syndromes commonly feature cleft lip and palate?","Patau syndrome (trisomy 13), Pierre Robin sequence, 22q11 deletion (palate).","Patau e Pierre Robin."],["1n03bglgm","What is the derivation of the anterior pituitary?","Rathke pouch (surface ectoderm from the roof of the oral cavity).","Bolsa de Rathke."],["nf7hwm1a2","What is the derivation of the posterior pituitary?","Neuroectoderm (infundibulum from the diencephalon).","Neuroectoderma."],["suwiep86e","What is holoprosencephaly?","Failure of the left and right hemispheres to separate (weeks 5-6); associated with SHH mutations, Patau syndrome, fetal alcohol syndrome; cleft lip/palate, cyclopia in severe cases.","Hemisférios não se separam."],["lfzo0fw3m","What are the major steps of lung development?","Embryonic, pseudoglandular, canalicular, saccular, alveolar stages.","Cinco estágios."],["159u2ri11","Embryonic stage of lung development (weeks 4-7)?","Lung bud from the foregut; trachea and main bronchi form. Errors cause tracheoesophageal fistula.","Broto pulmonar."],["1mvdt2u1f","Pseudoglandular stage of lung development (weeks 5-17)?","Conducting airways (to terminal bronchioles) form; no respiration possible; fetal breathing movements begin.","Vias de condução."],["1z53cm5qe","Canalicular stage of lung development (weeks 16-25)?","Respiratory bronchioles, alveolar ducts, and pulmonary capillaries form; type II pneumocytes begin to produce surfactant around week 20; respiration possible near the end (week 25).","Bronquíolos respiratórios e capilares."],["1fxhbnt31","Saccular stage of lung development (week 24 to birth)?","Terminal sacs (primitive alveoli) form; type I and type II pneumocytes differentiate.","Sacos terminais."],["d41q51ch9","Alveolar stage of lung development (week 36 to 8 years)?","Alveoli increase greatly in number; at birth about 20-70 million, adults about 300-400 million.","Alvéolos se multiplicam."],["1dxelzh3p","What is pulmonary hypoplasia?","Poorly developed bronchial tree; associated with congenital diaphragmatic hernia and bilateral renal agenesis (Potter sequence).","Pulmão pouco desenvolvido."],["13d01d1fr","What is a bronchogenic cyst?","Abnormal budding of the foregut and dilation of terminal or large bronchi; usually asymptomatic but can drain poorly, causing infection.","Brotamento anormal."],["1mt673nbd","What is the most common type of tracheoesophageal fistula?","Esophageal atresia with distal tracheoesophageal fistula (85%).","Atresia com fístula distal."],["1p25j5kck","Clinical features of esophageal atresia with TEF?","Drooling, choking, vomiting with first feeding, inability to pass a nasogastric tube, polyhydramnios in utero, air in stomach (distal TEF).","Engasgo ao mamar."],["1sxqmqp1u","What is an H-type tracheoesophageal fistula?","Fistula without atresia; presents later with recurrent aspiration pneumonia.","Fístula sem atresia."],["1j765it1h","How does the diaphragm form?","From the septum transversum, pleuroperitoneal folds, body wall, and dorsal mesentery of the esophagus. 'Several Parts Build Diaphragm'.","Quatro origens."],["1ceuz0e1m","Why is the diaphragm innervated by C3-C5?","It develops in the cervical region and descends, bringing the phrenic nerve with it. C3, 4, 5 keeps the diaphragm alive.","Desce do pescoço."],["1q0ecfyud","What is a congenital diaphragmatic hernia?","Abdominal structures enter the thorax due to defective pleuroperitoneal membrane, most commonly on the left (posterolateral, Bochdalek).","Abdome entra no tórax."],["m7brzi1tg","Clinical features of congenital diaphragmatic hernia?","Respiratory distress at birth, scaphoid abdomen, bowel sounds in chest, pulmonary hypoplasia on the affected side.","Abdome escavado e pulmão hipoplásico."],["43nczohyc","What is a Morgagni hernia?","Anterior (retrosternal) diaphragmatic hernia; less common.","Hérnia anterior."],["xm9l7v1oc","What is a hiatal hernia?","Stomach herniates upward through the esophageal hiatus of the diaphragm.","Estômago sobe."],["2w3rw02ro","Which part of the face derives from neural crest besides skeletal elements?","Most of the facial connective tissue and bones (not muscles, which come from arch mesoderm).","Tecido conjuntivo facial."],["wjb8u6tl6","What does the otic placode give rise to?","Inner ear (membranous labyrinth).","Ouvido interno."],["lec61t1on","Which pharyngeal arch structures form the middle ear ossicles?","Malleus and incus from the 1st arch; stapes from the 2nd arch.","Ossículos dos arcos 1 e 2."],["1kpqmz6tf","Which muscles of the middle ear derive from which arches?","Tensor tympani from the 1st arch (CN V3); stapedius from the 2nd arch (CN VII).","Tensor do tímpano e estapédio."],["1hluult1j","What is the embryological origin of the external ear?","Auricular hillocks from 1st and 2nd arches; external auditory meatus from the 1st cleft.","Saliências auriculares."],["2oa9zt8wt","What is the tympanic membrane's embryologic origin?","All three germ layers: ectoderm (1st cleft), mesoderm (arch), endoderm (1st pouch).","Três folhetos."],["uxalpd1cf","Where does the eye lens derive from?","Surface ectoderm (lens placode).","Ectoderma superficial."],["1ml9dbdze","Where does the retina derive from?","Neuroectoderm (optic cup).","Neuroectoderma."],["2az7gl1ty","What is a coloboma?","Failure of the choroid fissure to close, causing a defect in the iris, retina, or choroid (keyhole pupil); associated with CHARGE syndrome.","Fissura não fecha."],["9eszjy487","What does CHARGE syndrome include?","Coloboma, Heart defects, Atresia of choanae, Retardation of growth, Genital abnormalities, Ear anomalies (CHD7 gene).","Síndrome CHARGE."],["o3h4ak1m6","What is the derivation of the thymus?","Endoderm of the 3rd pharyngeal pouch (epithelial reticular cells); lymphocytes from bone marrow (mesoderm).","Terceira bolsa."],["d1xdhb9nc","Which structures derive from the foregut?","Pharynx to duodenum (proximal), lungs, liver, gallbladder, pancreas, spleen (mesoderm in dorsal mesentery).","Faringe ao duodeno."],["1vhitkq15","Which artery supplies the foregut?","Celiac trunk.","Tronco celíaco."],["pi6ay04f3","Which part of the duodenum is foregut vs midgut?","Proximal duodenum up to the ampulla of Vater is foregut; distal duodenum is midgut.","Proximal antes da papila."],["19t1ie91l","Which structures derive from the midgut?","Distal duodenum to proximal two-thirds of transverse colon; supplied by the superior mesenteric artery.","Médio."],["1dp0hka9z","Which structures derive from the hindgut?","Distal third of transverse colon to upper anal canal (above pectinate line); supplied by inferior mesenteric artery.","Posterior."],["ncqvcc12h","What is the cause of a ventricular septal defect in the membranous septum?","Failure of the endocardial cushions, aorticopulmonary septum, and muscular septum to fuse.","Septos não se fundem."],["1hokm9cym","What causes an ostium secundum ASD?","Excessive resorption of septum primum or inadequate septum secundum.","Reabsorção excessiva."],["1e7sgrgkh","What causes an ostium primum ASD?","Failure of the septum primum to fuse with the endocardial cushions (seen in Down syndrome).","Falha do septo primo."],["asi7og13d","What causes a sinus venosus ASD?","Defect near the SVC entry, often with partial anomalous pulmonary venous return.","Perto da cava superior."],["1q38bes1f","Why is coarctation of the aorta related to the ductus arteriosus?","Ductal tissue extends into the aorta; when it constricts after birth, it narrows the aorta (juxtaductal coarctation).","Tecido ductal na aorta."],["1l7k70no1","What is the fetal heart rate range considered normal?","110-160 bpm.","110 a 160 bpm."],["ttn0n910p","What happens to the ductus venosus after birth?","Closes within days, becoming the ligamentum venosum.","Vira ligamento venoso."],["1lsml4az7","What happens to umbilical vessels after birth?","Constrict and obliterate: umbilical arteries become medial umbilical ligaments; umbilical vein becomes ligamentum teres.","Viram ligamentos."],["h5a96s1yi","What is a double aortic arch?","Persistent right and left 4th arches forming a vascular ring compressing trachea and esophagus.","Dois arcos persistentes."],["zklkjm1sa","What is aberrant right subclavian artery (arteria lusoria)?","Right subclavian arises from the descending aorta and passes behind the esophagus; can cause dysphagia (dysphagia lusoria).","Subclávia atrás do esôfago."],["urxl803lc","What does 22q11 deletion cause in the heart and why?","Conotruncal defects because of failed neural crest migration into the outflow tract and pharyngeal arches.","Defeitos conotruncais."],["9jukoq1bp","Which arch derivative is affected in first arch syndromes like Treacher Collins?","Mandible and zygomatic hypoplasia, ear defects, conductive hearing loss (neural crest cell dysfunction).","Mandíbula e zigoma."],["fnmt4w1oy","What is the embryological basis of a cervical rib?","Overgrowth of the costal process of C7; can compress subclavian artery or brachial plexus (thoracic outlet syndrome).","Costela extra de C7."],["lvtp2m13i","What is the derivation of the sternocleidomastoid and trapezius?","Occipital somites/lateral plate mesoderm; innervated by CN XI.","Mesoderma dos somitos."],["1jroee3xm","What is the derivation of the laryngeal muscles and their innervation?","4th and 6th arches; innervated by superior laryngeal and recurrent laryngeal nerves (CN X).","Arcos 4 e 6."],["1bt2dm51s","Which nerve gives taste to the anterior two-thirds of the tongue?","CN VII via chorda tympani.","Corda do tímpano."],["1g95zkq13","Which nerve gives general sensation to the anterior two-thirds of the tongue?","CN V3 (lingual nerve).","Nervo lingual."],["1dsfa7c1i","Which nerve gives taste and sensation to the posterior one-third of the tongue?","CN IX.","Glossofaríngeo."],["bqlafuglx","Which nerve supplies taste to the epiglottic region and extreme back of tongue?","CN X.","Vago."],["eudzbg10e","Which tongue muscle is innervated by CN X?","Palatoglossus.","Palatoglosso."],["1elg2gc1a","Which pharyngeal arch gives rise to the muscles of the soft palate?","4th arch (levator veli palatini via CN X); tensor veli palatini from 1st arch (CN V3).","Quarto arco."],["t47q5xmwc","What does failure of the 2nd arch to overgrow the 3rd and 4th arches cause?","Persistent cervical sinus, leading to branchial cleft cyst or fistula.","Cisto branquial."],["q2qqbbi3f","What is a preauricular sinus or tag?","Minor anomaly of auricular hillock development (1st and 2nd arches); may be associated with renal anomalies.","Anomalia de orelha."],["1iduhrka1","What is the significance of low-set ears in a newborn?","Can be associated with chromosomal anomalies (trisomies) and renal anomalies (Potter sequence).","Trissomias e Potter."],["1yq4ovpy4","What is choanal atresia?","Failure of the oronasal membrane to rupture; newborns (obligate nasal breathers) become cyanotic with feeding and pink when crying.","Membrana não se rompe."],["1t1ykif5x","How is choanal atresia diagnosed?","Inability to pass a catheter through the nose into the oropharynx; CT confirms.","Sonda não passa."],["mzgsnl1fu","What is the derivation of the trachea's epithelium vs cartilage?","Epithelium from endoderm; cartilage and smooth muscle from splanchnic mesoderm (laryngeal cartilages from neural crest).","Endoderma e mesoderma."],["meywsw2mn","What is the tracheoesophageal septum?","Divides the foregut into the ventral trachea and dorsal esophagus; defects cause TEF.","Separa traqueia e esôfago."],["1fcjd5s1k","What maternal finding suggests esophageal atresia during pregnancy?","Polyhydramnios (fetus cannot swallow amniotic fluid).","Polidrâmnio."],["10prsxw19","What is the cardiogenic region where the heart forms?","Splanchnic mesoderm at the cranial end of the embryo (cardiogenic field), forming paired endocardial tubes that fuse.","Mesoderma esplâncnico."],["131qxmpft","What is the role of the dorsal mesocardium?","Suspends the heart tube; its breakdown forms the transverse pericardial sinus.","Forma o seio pericárdico."],["pqhthn1gw","What gives rise to the coronary arteries?","Proepicardium cells that form vessels connecting to the aortic root.","Proepicárdio."],["1ouedsuna","What is the main embryologic cause of tricuspid atresia?","Abnormal fusion of endocardial cushions leading to absent tricuspid valve.","Coxins anormais."],["4xdw5r16g","What results from failure of the truncal ridges to fuse?","Persistent truncus arteriosus.","Tronco arterioso persistente."],["1g3ufaibb","What results from failure of the aorticopulmonary septum to spiral?","Transposition of the great arteries.","Transposição."],["1fuyrm54v","What results from unequal division of the truncus with anterior septum displacement?","Tetralogy of Fallot.","Tetralogia de Fallot."],["e8ps8bar5","Why is the fetal pulmonary artery pressure higher than aortic pressure?","High pulmonary vascular resistance; this drives blood through the ductus arteriosus to the aorta.","Resistência pulmonar alta."],["1pccxdb12","What is persistent pulmonary hypertension of the newborn?","Failure of pulmonary vascular resistance to fall after birth, maintaining right-to-left shunting through PDA/foramen ovale; associated with meconium aspiration, sepsis, maternal NSAID/SSRI use.","Resistência não cai."],["1r97roa1f","Why can maternal NSAID use in the third trimester harm the fetus?","Premature closure of the ductus arteriosus (and oligohydramnios).","Fecha o canal arterial."],["1ivec7gs6","What is the fetal oxygen saturation in the descending aorta vs ascending aorta?","Ascending aorta is better oxygenated (from foramen ovale stream), supplying the brain and heart; descending aorta receives mixed blood from the ductus.","Ascendente mais oxigenada."],["1rd3xwg19","What does the 5th pharyngeal arch form?","It regresses (no major adult derivatives).","Regride."],["1sl77xp1l","What is the derivation of the stylohyoid ligament?","2nd pharyngeal arch (Reichert cartilage).","Segundo arco."],["1j5okcca5","Which cranial nerve supplies the muscles of mastication?","CN V3 (mandibular branch of trigeminal).","Trigêmeo."],["b4p16m1ik","Which cranial nerve supplies the stylopharyngeus?","CN IX.","Glossofaríngeo."],["ozwvb14sn","What is velocardiofacial syndrome?","Part of 22q11.2 deletion: palate anomalies, facial dysmorphism, cardiac defects, learning difficulties.","Deleção 22q11."],["16j7n4fn6","What is the embryologic basis of an ectopic parathyroid gland?","Abnormal migration of 3rd or 4th pouch derivatives; inferior parathyroids may be in the thymus or mediastinum.","Migração anormal."],["1r905z7qd","Where may an ectopic inferior parathyroid adenoma be found?","Anterior mediastinum within the thymus.","Mediastino no timo."],["z48776w1j","What is a lingual thyroid's clinical risk?","May be the only functional thyroid tissue; removal can cause hypothyroidism.","Pode ser a única tireoide."],["1barh77qx","What gives rise to the epiglottis?","4th pharyngeal arch (hypobranchial eminence).","Quarto arco."],["1o9e8vdgr","What is a laryngotracheal groove?","Ventral outgrowth of the foregut that forms the respiratory diverticulum (lung bud).","Origem do pulmão."]]},{"name":"03 - Embryology (Part 3).csv","cards":[["188r5nj1y","How does the midgut develop during weeks 6-10?","Physiologic herniation of the midgut through the umbilical ring (week 6), 270-degree counterclockwise rotation around the SMA, and return to the abdominal cavity (week 10).","Herniação fisiológica e rotação."],["12ue0tq1p","What is gastroschisis?","Extrusion of abdominal contents through an abdominal wall defect, usually right of the umbilicus; not covered by peritoneum or amnion.","Vísceras sem saco ao lado do umbigo."],["226e9piq7","What is omphalocele?","Persistent herniation of abdominal contents into the umbilical cord, covered by peritoneum and amnion (sac).","Vísceras dentro de saco no umbigo."],["1gudy491u","Which abdominal wall defect is associated with chromosomal abnormalities?","Omphalocele (trisomy 13, 18, Beckwith-Wiedemann); gastroschisis is usually isolated.","Onfalocele."],["c6ax13jv0","Mnemonic for gastroschisis vs omphalocele?","Gastroschisis: guts spill out without a sac. Omphalocele: sealed in a sac (O = covered).","Gastrosquise sem saco."],["r9aa7c2iz","What is malrotation of the midgut?","Incomplete rotation leading to abnormal positioning, Ladd bands (fibrous bands that can compress the duodenum), and risk of volvulus.","Rotação incompleta; bandas de Ladd."],["wa0ohk1x3","What is midgut volvulus's classic presentation in neonates?","Bilious vomiting in a newborn; ischemia and bowel necrosis; corkscrew on upper GI series.","Vômito bilioso no recém-nascido."],["sli3f31f0","What is duodenal atresia?","Failure of duodenal recanalization; double bubble on x-ray, bilious vomiting (if distal to ampulla), polyhydramnios; associated with Down syndrome.","Dupla bolha; Down."],["o94ky81j0","What is jejunal or ileal atresia?","Disruption of mesenteric vessels (vascular accident) causing ischemic necrosis; apple peel atresia; bilious vomiting, abdominal distension.","Acidente vascular intrauterino."],["1iyi6tg1j","How does duodenal atresia differ mechanistically from jejunal atresia?","Duodenal: failure to recanalize. Jejunal/ileal: vascular accident (ischemia).","Falha de recanalização versus isquemia."],["1wkpbj31t","What is hypertrophic pyloric stenosis?","Hypertrophy of the pylorus causing gastric outlet obstruction: palpable olive-shaped mass, projectile nonbilious vomiting at 2-6 weeks.","Oliva palpável; vômito em jato."],["fh53irw9k","Which metabolic disturbance occurs in pyloric stenosis?","Hypokalemic hypochloremic metabolic alkalosis.","Alcalose hipoclorêmica e hipocalêmica."],["bmewx01mk","Risk factors for pyloric stenosis?","Firstborn males, exposure to macrolides (e.g., erythromycin) in early infancy.","Primogênito homem; macrolídeos."],["1kxanvz1o","Treatment of pyloric stenosis?","Correct electrolytes, then surgical pyloromyotomy.","Piloromiotomia."],["1xqo852c3","How does the pancreas develop?","Ventral and dorsal pancreatic buds from foregut endoderm fuse; ventral bud forms the uncinate process and main pancreatic duct (with dorsal bud), dorsal bud forms body, tail, isthmus, and accessory duct.","Brotos ventral e dorsal se fundem."],["i1qsnsdw5","What is annular pancreas?","Ventral pancreatic bud abnormally encircles the 2nd part of the duodenum, forming a ring that may cause duodenal narrowing.","Anel ao redor do duodeno."],["g1pj4a1kw","What is pancreas divisum?","Ventral and dorsal parts fail to fuse at 7 weeks; usually asymptomatic but may cause chronic abdominal pain or pancreatitis.","Ductos não se fundem."],["15pyfyd1r","Where does the spleen develop from?","Mesoderm within the dorsal mesentery (foregut is supplied by celiac artery even though spleen is mesodermal).","Mesoderma no mesentério dorsal."],["1dsmso09c","Where does the liver develop from?","Hepatic diverticulum (endoderm) of the foregut; Kupffer cells and connective tissue are mesoderm.","Divertículo hepático."],["xttp871lg","What is biliary atresia?","Obliteration of extrahepatic bile ducts in infancy: persistent jaundice beyond 2 weeks, dark urine, acholic stools, hepatomegaly; conjugated hyperbilirubinemia.","Ductos biliares obliterados."],["k2yoei13r","Treatment of biliary atresia?","Kasai procedure (hepatoportoenterostomy), often ultimately liver transplant.","Cirurgia de Kasai."],["15z98n4mn","What is Hirschsprung disease?","Congenital megacolon due to lack of enteric ganglion cells (failure of neural crest cell migration) in the distal colon; rectum always involved.","Falta de gânglios no reto."],["1j5wvpt1q","Clinical features of Hirschsprung disease?","Failure to pass meconium within 48 hours, bilious emesis, abdominal distension, explosive stool on rectal exam (squirt sign).","Não elimina mecônio."],["1hfa34lly","Diagnosis and treatment of Hirschsprung disease?","Rectal suction biopsy shows absent ganglion cells; resection of the aganglionic segment.","Biópsia retal e ressecção."],["1qafs6k1j","Which gene is associated with Hirschsprung disease?","RET (loss of function); associated with Down syndrome.","RET."],["13oir511s","What is meconium ileus associated with?","Cystic fibrosis (thick meconium obstructing the ileum).","Fibrose cística."],["1s2exnm72","What is the pectinate (dentate) line?","Formed where endoderm (hindgut) meets ectoderm (proctodeum).","Encontro de endoderma e ectoderma."],["zb48r21a9","What drains and innervates above the pectinate line?","Internal hemorrhoids (painless), adenocarcinoma; superior rectal artery (IMA), superior rectal vein to IMV (portal); visceral innervation; drains to internal iliac nodes.","Hemorroida interna indolor."],["zgso766im","What drains and innervates below the pectinate line?","External hemorrhoids (painful), squamous cell carcinoma; inferior rectal artery (internal pudendal), inferior rectal vein to IVC; somatic innervation (pudendal nerve); drains to superficial inguinal nodes.","Hemorroida externa dolorosa."],["m5fay31ov","What is imperforate anus?","Failure of the anal membrane to perforate; part of VACTERL association.","Ânus não perfurado."],["9duufc15u","What are the three stages of kidney development?","Pronephros (week 4, degenerates), mesonephros (functions as interim kidney in the first trimester, forms male genital ducts), metanephros (permanent kidney, begins week 5).","Pronefro, mesonefro, metanefro."],["8i4p27hoz","What are the two components of the metanephros?","Ureteric bud (derived from caudal mesonephric duct) and metanephric mesenchyme (blastema).","Broto ureteral e blastema."],["l1bkhm1q3","What does the ureteric bud form?","Ureter, pelvis, calyces, and collecting ducts.","Ureter e ductos coletores."],["1cgbgzi14","What does the metanephric mesenchyme form?","Glomerulus through the distal convoluted tubule (nephron).","Néfron."],["rftz19zcs","What is the last part of the urinary system to canalize?","Ureteropelvic junction; the most common site of fetal obstruction (hydronephrosis).","Junção pieloureteral."],["tuj6gnhsn","What is bilateral renal agenesis?","Failure of the ureteric bud to induce metanephric mesenchyme, leading to oligohydramnios and Potter sequence.","Sem rins; Potter."],["1x5e7zy1m","What is multicystic dysplastic kidney?","Abnormal interaction between the ureteric bud and metanephric mesenchyme: nonfunctional kidney of cysts and connective tissue; usually unilateral, contralateral kidney hypertrophies.","Rim de cistos sem função."],["1mq7e74b4","What is a duplex collecting system?","Bifurcation of the ureteric bud before it enters metanephric blastema creates a Y-shaped bifid ureter, or two ureteric buds; associated with vesicoureteral reflux and obstruction.","Ureter duplo."],["1dcylmz1o","What is posterior urethral valves?","Membrane remnant in the posterior urethra of males causing urinary tract obstruction; hydronephrosis, dilated bladder, oligohydramnios.","Membrana na uretra posterior."],["1u2olotzh","What is a horseshoe kidney?","Inferior poles of both kidneys fuse; the kidney gets trapped under the inferior mesenteric artery as it ascends; usually functions normally.","Rim em ferradura."],["2gcq8514u","Which conditions are associated with horseshoe kidney?","Turner syndrome, trisomies 13, 18, 21; increased risk of hydronephrosis, stones, infection, Wilms tumor, renal cancer.","Turner e trissomias."],["mcepo71i1","Why does the kidney's blood supply change during development?","The kidneys ascend from the pelvis to the lumbar region and receive successively higher arterial branches; accessory renal arteries are common remnants.","Rins sobem e trocam artérias."],["ir1xayzmy","What is a pelvic kidney?","Failure of the kidney to ascend from the pelvis (ectopic kidney).","Rim não sobe."],["ej27od11b","What is ureteropelvic junction obstruction?","Most common cause of hydronephrosis in fetuses and neonates (incomplete recanalization).","Causa comum de hidronefrose."],["16q5hw44u","Which genital structure arises from the mesonephric (Wolffian) duct?","Male internal structures (except prostate): Seminal vesicles, Epididymis, Ejaculatory duct, Ductus deferens (SEED).","Epidídimo, deferente, vesícula seminal."],["t4qj082yz","What does the paramesonephric (Müllerian) duct form?","Female internal structures: fallopian tubes, uterus, upper portion of the vagina (lower portion from urogenital sinus).","Trompas, útero, vagina superior."],["1giaz0drw","What does Sertoli cell secretion of Müllerian inhibitory factor do?","Causes regression of the paramesonephric (Müllerian) ducts in males.","Faz regredir os ductos de Müller."],["ujaiva1sd","What does Leydig cell testosterone do in male development?","Stimulates development of mesonephric (Wolffian) ducts.","Desenvolve os ductos de Wolff."],["19udiu013","What gene determines testis development?","SRY gene on the Y chromosome, producing testis-determining factor.","SRY."],["wmsweeedm","What does dihydrotestosterone (DHT) do in male development?","Differentiates external genitalia (penis, scrotum) and prostate.","Genitália externa e próstata."],["n3kmmh1q2","What is the default sexual development without SRY?","Female development (ovaries, Müllerian derivatives, female external genitalia).","Feminino."],["101vy2uyw","What happens in Müllerian agenesis (Mayer-Rokitansky-Küster-Hauser syndrome)?","46,XX female with primary amenorrhea, absent uterus and upper vagina, normal ovaries and secondary sexual characteristics.","Sem útero com ovários normais."],["px303x1cl","What causes a bicornuate uterus?","Incomplete fusion of the paramesonephric ducts; associated with urinary tract abnormalities and infertility.","Fusão incompleta."],["xkd6e1ldx","What is a septate uterus?","Incomplete resorption of the septum after fusion of Müllerian ducts; most common uterine anomaly; recurrent pregnancy loss; treat with septoplasty.","Septo não reabsorvido."],["1ce2j9k1e","What is uterus didelphys?","Complete failure of fusion of Müllerian ducts, producing double uterus, cervix, and vagina; pregnancy possible.","Útero duplo."],["1iw4gb8op","What is the male homolog of the female clitoris?","Glans penis (from genital tubercle).","Glande."],["1qkownq19","What is the male homolog of the labia minora?","Ventral shaft of penis (penile urethra) (from urogenital folds).","Face ventral do pênis."],["1lmlb2y14","What is the male homolog of the labia majora?","Scrotum (from labioscrotal swellings).","Escroto."],["xz7gd71bd","What is the male homolog of the greater vestibular (Bartholin) glands?","Bulbourethral (Cowper) glands (from urogenital sinus).","Glândulas bulbouretrais."],["ydy41tdy2","What is the male homolog of the Skene paraurethral glands?","Prostate gland (from urogenital sinus).","Próstata."],["zhpx9w11p","What is the male homolog of the ovary?","Testis.","Testículo."],["benhmv1m3","What is the remnant of the mesonephric duct in females?","Gartner duct (can form cyst in the vaginal wall).","Ducto de Gartner."],["1fclpmu13","What is the remnant of the paramesonephric duct in males?","Appendix testis.","Apêndice testicular."],["stmu6x1uz","What is hypospadias?","Abnormal opening of the penile urethra on the ventral surface due to failure of the urethral folds to fuse.","Abertura ventral da uretra."],["1jz36yzb9","What is epispadias?","Abnormal opening of the penile urethra on the dorsal surface due to faulty positioning of the genital tubercle; associated with bladder exstrophy.","Abertura dorsal da uretra."],["7893na9hx","Mnemonic for epispadias vs hypospadias?","Hypospadias = hypo is below (ventral). Epispadias: 'when you have epispadias, you hit your eye when you pee'.","Hipo é embaixo."],["q96o491i8","What is the gubernaculum?","Band of fibrous tissue that guides testicular descent; in females forms the ovarian ligament and round ligament of uterus.","Guia a descida do testículo."],["gj6wn21oy","What is the processus vaginalis?","Evagination of peritoneum; in males forms the tunica vaginalis; normally obliterates.","Evaginação do peritônio."],["18kv2a6l9","What is the consequence of a persistent processus vaginalis?","Indirect inguinal hernia or hydrocele (communicating).","Hérnia indireta ou hidrocele."],["1bik5ii14","What is cryptorchidism?","Undescended testis; increased risk of germ cell tumors and infertility; orchiopexy before 1 year.","Testículo não descido."],["idezivrqa","How do the testes and ovaries drain venously?","Left gonadal vein to the left renal vein; right gonadal vein directly to the IVC.","Esquerda para a renal."],["1gqmy6xhv","Why is a left-sided varicocele more common?","Left gonadal vein drains into the left renal vein at a right angle; compression by the SMA (nutcracker) increases pressure.","Ângulo da veia renal."],["1rofcrnhg","Which lymph nodes drain the testes and ovaries?","Para-aortic lymph nodes.","Para-aórticos."],["1c9x7242m","Which lymph nodes drain the scrotum?","Superficial inguinal nodes.","Inguinais superficiais."],["p3wrwvsw4","What does the neural plate form?","Neural tube (by neurulation, week 3-4) and neural crest cells.","Tubo neural e crista."],["1jcbw7pu4","What induces neural plate formation?","The notochord (via SHH and other signals).","Notocorda."],["l6sl916u0","What are the primary brain vesicles?","Prosencephalon (forebrain), mesencephalon (midbrain), rhombencephalon (hindbrain).","Prosencéfalo, mesencéfalo, rombencéfalo."],["6mzvmu1nr","What does the telencephalon form?","Cerebral hemispheres and lateral ventricles.","Hemisférios."],["gi4pi1qmf","What does the diencephalon form?","Thalamus, hypothalamus, third ventricle, retina.","Tálamo e hipotálamo."],["144s3ogp1","What does the mesencephalon form?","Midbrain and cerebral aqueduct.","Mesencéfalo."],["reimnb1wx","What does the metencephalon form?","Pons and cerebellum; upper part of the 4th ventricle.","Ponte e cerebelo."],["1yvo26e1k","What does the myelencephalon form?","Medulla and lower part of the 4th ventricle.","Bulbo."],["9maftrdc0","What are the alar and basal plates of the neural tube?","Alar plate (dorsal): sensory. Basal plate (ventral): motor. Same orientation as spinal cord (A before B, sensory before motor dorsally).","Alar sensitiva; basal motora."],["1im73zt16","What is a neural tube defect?","Failure of the neural tube to close (normally by week 4).","Tubo neural não fecha."],["1obt7211r","What lab findings indicate an open neural tube defect?","Increased AFP in amniotic fluid and maternal serum; increased acetylcholinesterase in amniotic fluid.","AFP e acetilcolinesterase."],["jr4s3x1sj","What is spina bifida occulta?","Failure of the caudal neuropore to close without herniation; tuft of hair or dimple at the lumbosacral level; dura intact; normal AFP.","Defeito sem herniação."],["44wwrx1yb","What is a meningocele?","Meninges (but not neural tissue) herniate through a bony defect.","Hérnia só das meninges."],["irqmgvv5q","What is a myelomeningocele?","Meninges and neural tissue (spinal cord) herniate through the bony defect; associated with Chiari II malformation and hydrocephalus.","Meninges e medula herniam."],["1a5yojkz1","What is myeloschisis?","Exposed, unfused neural tissue without skin or meningeal covering (most severe spina bifida).","Tecido neural exposto."],["1tp5bok1u","What is anencephaly?","Failure of the rostral neuropore to close, leading to no forebrain and open calvarium; polyhydramnios; elevated AFP; associated with maternal type 1 diabetes.","Sem prosencéfalo."],["x1pgz4hc3","What is Chiari I malformation?","Ectopia of cerebellar tonsils >3-5 mm below foramen magnum; usually asymptomatic in childhood, presents in adulthood with headaches and cerebellar symptoms; associated with syringomyelia.","Amígdalas cerebelares descidas."],["1xkc3w91s","What is Chiari II malformation?","Herniation of the cerebellar vermis and tonsils through the foramen magnum with aqueductal stenosis and noncommunicating hydrocephalus; associated with lumbosacral myelomeningocele.","Vérmis desce com hidrocefalia."],["yrskm4phy","What is Dandy-Walker malformation?","Agenesis of the cerebellar vermis with cystic enlargement of the 4th ventricle that fills the enlarged posterior fossa; associated with noncommunicating hydrocephalus and spina bifida.","Agenesia do vérmis."],["fln8zsi18","What is syringomyelia?","Cystic cavity (syrinx) in the central spinal cord, often C8-T1, damaging anterior white commissure fibers (spinothalamic): cape-like bilateral loss of pain and temperature in upper extremities.","Cavidade na medula."],["b0sflqyba","Which malformation is syringomyelia commonly associated with?","Chiari I malformation.","Chiari I."],["1y6jqi610","What is lissencephaly?","Failure of neuronal migration resulting in smooth brain without sulci and gyri.","Cérebro liso."],["1xxsrf212","What is the cause of microcephaly in congenital Zika or CMV?","Disruption of neural progenitor proliferation and neuronal death.","Lesão dos progenitores."],["a1pplj1ld","What is the embryologic origin of microglia?","Mesoderm (yolk sac macrophage lineage).","Mesoderma."],["1159896zg","What is the embryologic origin of oligodendrocytes and astrocytes?","Neuroectoderm (neural tube).","Neuroectoderma."],["3i81h11mo","What is the embryologic origin of Schwann cells?","Neural crest.","Crista neural."],["kbco3q1qe","Which structures do the dorsal root ganglia derive from?","Neural crest.","Crista neural."],["r7u8m2b7g","What is the limb bud formation timeline?","Upper and lower limb buds begin in week 4; digits form by apoptosis between them (weeks 6-8).","Semana 4."],["ajm6l410y","What causes syndactyly?","Failure of apoptosis between digits.","Falha da apoptose."],["1d1jz0ao0","What is the zone of polarizing activity?","Region at the posterior base of the limb bud that produces SHH and determines anterior-posterior axis (thumb vs little finger).","Produz SHH."],["o8cszabkz","What is the apical ectodermal ridge?","Thickened ectoderm at the tip of the limb bud that produces FGF to promote limb outgrowth (proximal-distal axis).","Produz FGF."],["1l5jnhc5x","What is the role of Wnt7 in the limb?","Dorsal ectoderm signal that establishes dorsal-ventral polarity.","Polaridade dorsoventral."],["12rhq5t71","What is achondroplasia's embryologic mechanism?","Constitutive FGFR3 activation impairs endochondral ossification (long bones), sparing intramembranous ossification (skull).","FGFR3 ativado."],["149fcq51c","What is the role of the somites?","Paraxial mesoderm segments forming sclerotome (vertebrae, ribs), myotome (skeletal muscle), and dermatome (dermis).","Vértebras, músculos e derme."],["q2poevefj","What forms the vertebral bodies?","Sclerotomes: caudal half of one sclerotome fuses with the cranial half of the next.","Fusão de esclerótomos."],["1n89vir12","What is Klippel-Feil syndrome?","Congenital fusion of cervical vertebrae: short neck, low hairline, limited neck motion.","Fusão de vértebras cervicais."],["xxge1u8v9","What is the embryologic origin of skeletal muscle?","Paraxial mesoderm (somites), except head muscles from pharyngeal arch mesoderm.","Somitos."],["tyqr171xc","What is the embryologic origin of smooth muscle of the gut?","Splanchnic (visceral) lateral plate mesoderm.","Mesoderma esplâncnico."],["1mmm3wfdc","What is the embryologic origin of the adrenal cortex vs medulla?","Cortex: mesoderm (coelomic epithelium). Medulla: neural crest.","Córtex mesoderma; medula crista."],["claj4i1hz","What tumor arises from adrenal medulla neural crest cells in children?","Neuroblastoma.","Neuroblastoma."],["1672e4jo9","What is the embryologic origin of the kidney?","Intermediate mesoderm.","Mesoderma intermediário."],["1ws7zmv1m","What is the embryologic origin of the gonads?","Intermediate mesoderm (genital ridge) with primordial germ cells migrating from the yolk sac.","Crista genital."],["rk4p6lxkr","What is the origin of primordial germ cells?","Epiblast, migrating via the yolk sac wall to the genital ridges.","Epiblasto."],["14bdkr81p","Where do extragonadal germ cell tumors occur and why?","Midline sites (mediastinum, retroperitoneum, sacrococcygeal, pineal) along the migration path of primordial germ cells.","Linha média."],["ryarbjt9m","What is the embryologic origin of the bladder?","Urogenital sinus (endoderm) except the trigone (mesonephric ducts, mesoderm).","Seio urogenital."],["c89xcal4z","What divides the cloaca?","Urorectal septum divides it into the urogenital sinus (anterior) and anorectal canal (posterior).","Septo urorretal."],["1vtxie2v8","What is the embryologic origin of the urethra?","Endoderm of the urogenital sinus (distal penile urethra from ectoderm in some descriptions).","Endoderma."],["1skaw4t2o","What is the embryologic origin of the prostate?","Endoderm of the urogenital sinus.","Endoderma."],["166p169bk","What is the embryologic origin of the lower third of the vagina?","Urogenital sinus (sinovaginal bulbs).","Seio urogenital."],["pizx0yc4m","What causes an imperforate hymen?","Failure of the vaginal plate to canalize; causes hematocolpos and primary amenorrhea with cyclic pain.","Placa vaginal não canaliza."],["psfq5t1n1","What is vaginal atresia vs transverse vaginal septum?","Both are failures of vaginal plate canalization or fusion; present with primary amenorrhea and cyclic pelvic pain.","Falhas de canalização."],["9j8v0otju","When do external genitalia become distinguishable?","Around week 10-12.","Semanas 10 a 12."],["1283rllzz","What drives development of male external genitalia?","DHT (from testosterone via 5-alpha reductase).","DHT."],["2hypqx19n","What happens to male development in 5-alpha-reductase deficiency?","Ambiguous or female-appearing external genitalia at birth with normal internal male structures; virilization at puberty.","Genitália ambígua até a puberdade."],["19ezge5qe","What is androgen insensitivity syndrome's internal anatomy?","Testes present (often intra-abdominal), Müllerian structures absent (MIF present), Wolffian structures absent or rudimentary; female external genitalia.","Testículos sem útero."],["1pj20xgsl","Where does the thyroid descend from and through what?","From the foramen cecum through the thyroglossal duct to the anterior neck.","Forame cego."],["wced7ro26","What is the embryologic origin of thyroid follicular cells?","Endoderm.","Endoderma."],["1rsc438vn","What is the embryologic origin of the parathyroid chief cells?","Endoderm of 3rd and 4th pharyngeal pouches.","Endoderma das bolsas."],["1j1bqdd16","What is the embryologic origin of the inner ear vs middle ear?","Inner ear: surface ectoderm (otic placode). Middle ear cavity: endoderm (1st pouch). Ossicles: neural crest (arches).","Ectoderma versus endoderma."],["f7if5d1ah","What is the embryologic origin of tooth enamel vs dentin?","Enamel: ectoderm (ameloblasts). Dentin: neural crest (odontoblasts).","Ectoderma e crista neural."],["1nn377n1d","What is the embryologic origin of the cornea?","Surface ectoderm (epithelium) and neural crest (stroma and endothelium).","Ectoderma e crista neural."],["wt5xbw1l6","What causes congenital cataracts?","Congenital infections (rubella), galactosemia, genetic syndromes, trisomies.","Rubéola e galactosemia."],["boum9w2rg","What is the embryologic origin of the iris muscles?","Neuroectoderm (sphincter and dilator pupillae).","Neuroectoderma."],["19iloaq18","What is the main determinant of gonadal sex vs phenotypic sex?","Gonadal sex depends on SRY; phenotypic sex depends on hormones (testosterone, DHT, MIF) and receptor function.","SRY e hormônios."],["1jksjvh16","What is a persistent Müllerian duct syndrome?","46,XY male with normal external genitalia but uterus and fallopian tubes due to MIF or MIF receptor deficiency; often cryptorchidism.","Homem com útero."],["1aaepyxjk","What is the role of the urorectal septum defect in development?","Can cause fistulas between the rectum and urinary tract or vagina (anorectal malformations).","Fístulas."],["1ns944lrc","What is exstrophy of the bladder?","Failure of the anterior abdominal wall to close over the bladder, exposing its mucosa; associated with epispadias.","Bexiga exposta."],["1usz72wbh","What is the urachus?","Remnant of the allantois connecting the bladder to the umbilicus; obliterates to form the median umbilical ligament.","Liga bexiga ao umbigo."],["1e5lqgo3b","Which kidney anomaly can result from failure of the ureteric bud to branch normally?","Renal hypoplasia or dysplasia.","Hipoplasia ou displasia."],["fl62xl6mt","What fetal finding suggests bilateral renal agenesis on ultrasound?","Severe oligohydramnios and absent bladder.","Oligoidrâmnio grave."],["vuvlj5hed","What happens to the mesonephric tubules in males?","Form efferent ductules connecting rete testis to epididymis.","Dúctulos eferentes."],["atoigruvf","What is the developmental origin of the seminal vesicle?","Mesonephric (Wolffian) duct.","Ducto de Wolff."],["1p2y4j6pl","What is the developmental origin of the epididymis?","Mesonephric duct (and mesonephric tubules for efferent ductules).","Ducto de Wolff."],["mjpy2ix7s","What is the derivation of the ductus deferens?","Mesonephric (Wolffian) duct.","Ducto de Wolff."],["1iuphw3p4","What is the derivation of the uterine tubes?","Unfused cranial portions of the paramesonephric (Müllerian) ducts.","Ductos de Müller."],["d0yfbo19d","What is the role of retinoic acid in development?","Regulates HOX gene expression; excess (isotretinoin) causes craniofacial, cardiac, and CNS malformations.","Regula genes HOX."],["qyqhdm90m","What is the earliest gut tube structure to form?","Primitive gut forms from incorporation of the yolk sac during embryonic folding (week 4).","Intestino primitivo."],["1iz7ss5ek","What is the derivation of gut epithelium vs gut smooth muscle?","Epithelium: endoderm. Smooth muscle and connective tissue: splanchnic mesoderm. Enteric neurons: neural crest.","Endoderma e mesoderma."],["cj2m2p1tf","What is the role of stomach rotation in development?","Stomach rotates 90 degrees clockwise around its longitudinal axis, making the left vagus anterior and right vagus posterior.","Rotação de 90 graus."],["yx45vk1tg","Why is the left vagal trunk anterior on the stomach?","Due to 90-degree clockwise rotation of the stomach during development.","Rotação do estômago."],["13md49k81","What is the origin of the lesser sac?","Formed by stomach rotation; space behind the stomach (omental bursa).","Bolsa omental."],["o2mp0robm","What is the ventral mesentery's derivatives?","Lesser omentum, falciform ligament, coronary and triangular ligaments of liver.","Omento menor e falciforme."],["19a38621s","What is the dorsal mesentery's derivatives?","Greater omentum, mesentery of small intestine, mesocolon, gastrosplenic and splenorenal ligaments.","Omento maior e mesentérios."],["1r963cvh2","What is the embryologic basis of intestinal duplication cysts?","Abnormal recanalization or diverticulum formation of the gut, lined by GI mucosa.","Recanalização anormal."],["xht9wu1b8","What is the embryologic basis of ectopic pancreatic tissue?","Pancreatic tissue in abnormal locations (stomach, duodenum, Meckel diverticulum).","Pâncreas em local anormal."],["zcqwmc192","What is an accessory spleen?","Splenic tissue that failed to fuse during development; often near the splenic hilum.","Baço extra."],["464x9ir6k","What is the role of the mesonephros in the female?","Largely regresses; remnants include epoophoron and paroophoron (and Gartner duct).","Regride."],["n0kr7aunb","What is a Wilms tumor's embryologic origin?","Persistent metanephric blastema (nephrogenic rests).","Blastema persistente."],["1lpjgl8kp","What is WAGR syndrome?","Wilms tumor, Aniridia, Genitourinary anomalies, Range of developmental delays (WT1 deletion on chromosome 11).","WT1 deletado."],["5pyz7flcp","What is Denys-Drash syndrome?","Wilms tumor, early-onset nephrotic syndrome (diffuse mesangial sclerosis), male pseudohermaphroditism (WT1 mutation).","Wilms e nefrose."],["m6dcgmju2","What is the embryologic basis of a hydrocele?","Fluid in a patent processus vaginalis (communicating) or tunica vaginalis (noncommunicating).","Processo vaginal patente."],["zoa37n1fk","How does a hydrocele differ from a varicocele on exam?","Hydrocele transilluminates; varicocele does not (bag of worms, worse standing).","Hidrocele transilumina."],["4l3ggq10y","What is the embryologic basis of a direct inguinal hernia?","Not embryologic; acquired weakness of the transversalis fascia in Hesselbach triangle (older men).","Fraqueza adquirida."]]}];
